// Tests for stage 7, Workflow AI (.claude/plans/stage7-spec.md §2, §4): the two modes and who gets them, the context,
// the generated catalog (regenerated by run_tests.sh = the committed wf_catalog.ts), the prompt and tool-schema sizes,
// the four tools (the repair loop, the greyed types never proposed, the free AI's size refusal), the two change kinds
// (Confirm = the automations function's save with ai_edited, never publish; the stale revision; the undo paths), the test
// provider's scripts and the 30-case eval set built in --dry mode. The automations function is a fake here (io.automations,
// recorded): its own steps (patch, validate generate) are tested in automations/tests.ts. Appended to tests.ts by
// run_tests.sh after WF_CATALOG_REGEN / WF_CATALOG_FILE / WF_EVAL_CASES; it only pushes a suite.
// deno-lint-ignore-file no-explicit-any

SUITES.push(async () => {
  const fs: any = await import("node:fs");
  const BEFORE = { userClient: io.userClient, automations: io.automations };
  const clone = (v: any) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
  const WID = "70000000-0000-4000-8000-000000000001";
  const VA = { id: "u-va7", full_name: "Vera Va", role: "va", permissions: { crm: true }, technician_name: null };
  const MK = { id: "u-mk7", full_name: "Mia Marketing", role: "marketing", permissions: {}, technician_name: null };
  const PROFILES: Record<string, any> = { "jwt-owner": OWNER, "jwt-manager": MANAGER, "jwt-tech": TECH };

  // ── a registry as the automations function exports it (the parts the gateway reads) ──
  const ok1 = { ok: true };
  const REG = {
    ok: true, v: 2,
    triggers: [
      { key: "newLead", label: "Lead created", availability: ok1, hidden: false, fields: { type: "object", properties: {} } },
      { key: "stage", label: "Pipeline stage changed", availability: ok1, hidden: false, fields: { type: "object", properties: {} } },
      { key: "review_received", label: "New Google review", availability: { ok: false, reason: "Needs the Google Business Profile connector" }, hidden: false },
    ],
    actions: [
      { key: "send_email", kind: "action", label: "Send email", availability: ok1, hidden: false,
        fields: { type: "object", properties: { subject: { type: "string" }, templateKey: { type: "string", "x-source": "catalog.templates", enum: ["welcome"], "x-enumLabels": ["welcome"] } } } },
      { key: "send_sms", kind: "action", label: "Send SMS", availability: { ok: false, reason: "Needs the phone line (Twilio)" }, hidden: false },
      { key: "ai_agent", kind: "action", label: "AI Agent", availability: { ok: false, reason: "Coming later" }, hidden: false },
      { key: "internal_notification", kind: "action", label: "Send internal notification", availability: ok1, hidden: false },
      { key: "add_tag", kind: "action", label: "Add lead tag", availability: ok1, hidden: false, fields: { type: "object", properties: { tags: { type: "array", items: { type: "string", "x-source": "catalog.tags", enum: ["vip"], "x-enumLabels": ["VIP"] } } } } },
      { key: "old_thing", kind: "action", label: "Old", availability: ok1, hidden: true },
    ],
    waits: [{ key: "period", kind: "wait", label: "For a set period of time", availability: ok1, hidden: false }],
    goals: [{ key: "stage_reached", kind: "goal", label: "Lead reached a stage", availability: ok1, hidden: false }],
    logic: [{ key: "if_else", kind: "if_else", label: "If / else", availability: ok1, hidden: false }],
    fields: [
      { key: "stage", source: "catalog.stages", values: [{ key: "quoted", label: "Quoted" }, { key: "booked", label: "Booked" }] },
      { key: "service", source: "catalog.services", values: [{ key: "split", label: "Split system" }] },
      { key: "lead.assigned_user", source: "catalog.people", values: [{ key: "u-owner", label: "Olivia Owner" }] },
    ],
  };
  const CANON = () => ({
    schema: 2, seq: 9, entry: "n1", triggers: [{ id: "t1", type: "stage", name: "Moved to Quoted", filters: { match: "all", segments: [{ match: "all", rules: [{ field: "stage", op: "is", v: "quoted" }] }] } }],
    nodes: {
      n1: { kind: "wait", type: "period", name: "Wait 2 days", config: { n: 2, unit: "days" }, out: { next: "n4" } },
      n4: { kind: "action", type: "send_email", name: "Quote follow-up", config: { subject: "Your {service} quote", body: "Hi {first_name}" }, out: { next: "n8" } },
      n8: { kind: "action", type: "manual_call", config: { title: "Call {name}" }, out: { next: null } },
    },
  });

  // ── the fake automations function: the steps Workflow AI may call, on db.T.automations / automation_versions ──
  const REC: { jwt: string; step: string; body: any }[] = [];
  const FA: any = { validateQueue: [] as any[], waiting: 0, saveStatus: null as any };
  const rowOf = (db: any, id: string) => db.T.automations.find((a: any) => a.id === id && !a.deleted_at);
  const snap = (db: any, a: any) => { const no = db.T.automation_versions.filter((v: any) => v.automation_id === a.id).length + 1; db.T.automation_versions.push({ automation_id: a.id, version_no: no, definition: clone(a.definition), name: a.name, settings: clone(a.settings) }); return no; };
  const applyOps = (doc: any, ops: any[]) => {
    const d = clone(doc), errors: any[] = [];
    ops.forEach((op: any, i: number) => {
      if (op.op === "setNode" && d.nodes[op.id]) { const p = op.patch || {}; d.nodes[op.id] = { ...d.nodes[op.id], ...(p.name ? { name: p.name } : {}), config: { ...d.nodes[op.id].config, ...(p.config || {}) } }; }
      else if (op.op === "removeNode" && d.nodes[op.id]) { delete d.nodes[op.id]; for (const n of Object.values(d.nodes) as any[]) for (const k of Object.keys(n.out)) if (n.out[k] === op.id) n.out[k] = null; if (d.entry === op.id) d.entry = null; }
      else if (op.op === "addNode") { d.seq++; const id = "n" + d.seq; d.nodes[id] = { kind: op.node.kind, type: op.node.type, config: op.node.config || {}, out: { next: null } }; }
      else if (op.op === "removeTrigger" && d.triggers.some((t: any) => t.id === op.id)) d.triggers = d.triggers.filter((t: any) => t.id !== op.id);
      else if (op.op === "setSettings") d.__settings = { ...(d.__settings || {}), ...(op.patch || {}) };
      else if (op.op === "setEntry" && d.nodes[op.id]) d.entry = op.id;
      else errors.push({ code: "E_PATCH_ID", path: "/id", opIndex: i, text: "No such step" });
    });
    return { doc: d, errors };
  };
  async function fakeAuto(userSb: any, body: any): Promise<{ status: number; body: any }> {
    REC.push({ jwt: userSb && userSb.__jwt, step: body.step, body: clone(body) });
    const db = CUR, me = PROFILES[userSb && userSb.__jwt];
    if (!me || !(me.role === "owner" || me.role === "manager")) return { status: 403, body: { ok: false, reason: "owners and managers only" } };
    if (body.step === "registry") return { status: 200, body: clone(REG) };
    if (body.step === "validate") {
      const next = FA.validateQueue.shift();
      return next || { status: 200, body: { ok: true, errors: [], warnings: [{ code: "W_X", text: "A test warning" }], shapeChanged: false, idsRemoved: [], willDraft: false, waitingRunsAffected: 0 } };
    }
    if (body.step === "patch") {
      const a = rowOf(db, body.automation_id);
      if (!a) return { status: 404, body: { ok: false, reason: "workflow not found" } };
      if (body.outline === true) return { status: 200, body: { ok: true, revision: a.revision, name: a.name, enabled: a.enabled, outline: FA.outline || { entry: a.definition.entry, triggers: a.definition.triggers.map((t: any) => ({ id: t.id, type: t.type, name: t.name || null })), nodes: Object.entries(a.definition.nodes).map(([id, n]: any) => ({ id, kind: n.kind, type: n.type, name: n.name || null, config: n.config, out: n.out })) } } };
      if (body.base_revision !== a.revision) return { status: 409, body: { ok: false, reason: "conflict", revision: a.revision } };
      const p = applyOps(a.definition, body.ops);
      if (p.errors.length) return { status: 422, body: { ok: false, reason: "errors", errors: p.errors } };
      const sp = p.doc.__settings || null, settings = sp ? { ...a.settings, ...sp } : a.settings;
      delete p.doc.__settings;
      const was = a.definition.nodes, now = p.doc.nodes;
      const changedIds = Object.keys(now).filter((k) => JSON.stringify(now[k]) !== JSON.stringify(was[k])).sort(), idsRemoved = Object.keys(was).filter((k) => !(k in now)).sort();
      const triggersRemoved = a.definition.triggers.map((t: any) => t.id).filter((x: string) => !p.doc.triggers.some((t: any) => t.id === x)).sort();
      return { status: 200, body: { ok: true, definition: p.doc, settings, name: a.name, idMap: {}, errors: [], warnings: [], idsRemoved, changedIds, triggersRemoved, settingsChanged: sp ? Object.keys(sp).sort() : [], entryChanged: p.doc.entry !== a.definition.entry,
        shapeChanged: idsRemoved.length > 0, willDraft: a.enabled === true && body.ai_edited === true, waitingRunsAffected: FA.waiting, revision: a.revision } };
    }
    if (body.step === "save") {
      if (FA.saveStatus) return FA.saveStatus;
      if (body.automation_id == null) {
        const a = { id: "70000000-0000-4000-8000-0000000000" + String(10 + db.T.automations.length), business_id: "default", name: body.name, definition: clone(body.definition), settings: clone(body.settings), enabled: false, origin: body.ai_edited ? "ai" : "user", revision: 1, deleted_at: null };
        db.T.automations.push(a);
        return { status: 200, body: { ok: true, id: a.id, revision: 1, enabled: false, version_no: snap(db, a), drafted: false, errors: [], warnings: [] } };
      }
      const a = rowOf(db, body.automation_id);
      if (!a) return { status: 404, body: { ok: false, reason: "workflow not found" } };
      if (body.expected_revision !== a.revision) return { status: 409, body: { ok: false, reason: "conflict", revision: a.revision } };
      if (typeof body.expected_enabled === "boolean" && (a.enabled === true) !== body.expected_enabled) return { status: 409, body: { ok: false, reason: "status", enabled: a.enabled === true, revision: a.revision } };
      const was = a.enabled;
      Object.assign(a, { name: body.name, definition: clone(body.definition), settings: clone(body.settings), revision: a.revision + 1, enabled: body.ai_edited === true ? false : a.enabled });
      return { status: 200, body: { ok: true, id: a.id, revision: a.revision, enabled: a.enabled, version_no: snap(db, a), drafted: was === true && a.enabled === false, errors: [], warnings: [] } };
    }
    if (body.step === "restore") {
      const a = rowOf(db, body.automation_id);
      if (!a) return { status: 404, body: { ok: false, reason: "workflow not found" } };
      if (a.enabled) return { status: 409, body: { ok: false, reason: "published", text: "Switch to Draft first, or create a new workflow from this version" } };
      if (body.expected_revision != null && body.expected_revision !== a.revision) return { status: 409, body: { ok: false, reason: "conflict", revision: a.revision } };
      const v = db.T.automation_versions.find((x: any) => x.automation_id === a.id && x.version_no === body.version_no);
      if (!v) return { status: 404, body: { ok: false, reason: "version not found" } };
      Object.assign(a, { definition: clone(v.definition), name: v.name, revision: a.revision + 1 });
      return { status: 200, body: { ok: true, id: a.id, revision: a.revision, version_no: snap(db, a) } };
    }
    return { status: 400, body: { ok: false, reason: "unknown step" } };
  }
  io.automations = fakeAuto;
  io.userClient = (jwt: string) => ({ __jwt: jwt, from: (t: string) => CUR.from(t), rpc: (n: string, a: any) => CUR.rpc(n, a) });
  const wfWorld = (rows: any[] = []) => {
    const db = world({}, { automations: rows, automation_versions: [] });
    for (const a of rows) db.T.automation_versions.push({ automation_id: a.id, version_no: 1, definition: clone(a.definition), name: a.name, settings: clone(a.settings) });
    REC.length = 0; FA.validateQueue = []; FA.waiting = 0; FA.saveStatus = null; FA.outline = null;
    return db;
  };
  const canonRow = (o: any = {}) => ({ id: WID, business_id: "default", name: "Quote follow-up", definition: CANON(), settings: {}, enabled: false, origin: "user", revision: 4, deleted_at: null, ...o });
  const toolResult = (db: any, r: any, i = 0) => {
    const rows = msgs(db, convOf(r)).filter((m: any) => m.role === "user" && Array.isArray(m.content) && m.content[0] && m.content[0].type === "tool_result");
    const b = rows[i] ? rows[i].content[0] : null;
    if (!b) return null;
    let v: any = b.content; try { v = JSON.parse(b.content); } catch { /* an error text */ }
    return { isError: !!b.is_error, v };
  };
  const build = (db: any, input: any, jwt = "jwt-owner") => chat(db, { text: `[mock:tool propose_workflow ${JSON.stringify(input)}]`, mode: "workflow_build", context: { page: "settings" } }, jwt);
  const edit = (db: any, text: string, jwt = "jwt-owner", ctx: any = { page: "settings", workflowId: WID }) => chat(db, { text, mode: "workflow_edit", context: ctx }, jwt);
  const steps = () => REC.map((x) => x.step);
  const owner = appProfile(OWNER), manager = appProfile(MANAGER);

  // ── 1. modes, tools and change kinds: owners and managers only ──
  {
    const b = MODES.workflow_build, e = MODES.workflow_edit;
    eq([b.taskKey, b.effort, e.taskKey, e.effort], ["heavy", "medium", "heavy", "medium"], "Workflow AI modes: the heavy task, medium effort");
    eq([OWNER, MANAGER, TECH, VA, MK].map((p) => [b.allow!(appProfile(p)), e.allow!(appProfile(p))]), [[true, true], [true, true], [false, false], [false, false], [false, false]], "the modes are for owners and managers only");
    eq([toolsFor("workflow_build", owner).map((t) => t.name), toolsFor("workflow_edit", manager).map((t) => t.name)], [["propose_workflow", "workflow_options"], ["propose_workflow_edit", "read_workflow", "workflow_options"]], "build: options + propose; edit: options + read + propose the edit");
    eq(["technician", "va", "marketing"].map((r) => toolsFor("workflow_build", appProfile({ ...OWNER, role: r })).length + toolsFor("workflow_edit", appProfile({ ...OWNER, role: r })).length), [0, 0, 0], "no Workflow AI tool for the other roles");
    ok(!toolsFor("assistant", owner).some((t) => /workflow/.test(t.name)), "the assistant mode offers none of them");
    eq([CHANGE_KINDS.wf_create.allow(owner), CHANGE_KINDS.wf_edit.allow(manager), CHANGE_KINDS.wf_create.allow(appProfile(TECH)), CHANGE_KINDS.wf_edit.allow(appProfile(VA))], [true, true, false, false], "the change kinds: owners and managers");
    for (const n of ["propose_workflow", "propose_workflow_edit"]) ok(/Nothing changes until the person presses Confirm/.test(TOOLS[n].description) && /never say it is done/.test(TOOLS[n].description) && TOOLS[n].kind === "change", `${n}: a change tool that only proposes`);
    eq(WF_AI_STEPS, ["registry", "validate", "patch", "save", "restore"], "the only automations steps Workflow AI calls");
    let threw = "";
    try { await wfCall({ __jwt: "jwt-owner" }, { step: "publish", automation_id: WID, on: true }); } catch (x) { threw = String((x as Error).message); }
    ok(/not a Workflow AI step/.test(threw) && !REC.some((r) => r.step === "publish"), "wfCall refuses publish before anything is sent");
  }

  // ── 2. the context and the pre-stream gate ──
  {
    const db = wfWorld([canonRow()]);
    eq([validateInput({ page: "settings", workflowId: WID }, MODES.workflow_edit.contextSchema, "context").length, validateInput({ page: "settings", workflowId: "nope" }, MODES.workflow_edit.contextSchema, "context").length > 0,
      validateInput({ page: "settings" }, MODES.workflow_edit.contextSchema, "context").length > 0, validateInput({ builder: "fancy" }, MODES.workflow_build.contextSchema, "context").length > 0], [0, true, true, true],
      "the edit context needs the workflow's id (a uuid); builder is standard or advanced");
    let r = await chat(db, { text: "build it", mode: "workflow_build" }, "jwt-tech");
    eq([r.status, r.body && r.body.code], [400, "unknown_mode"], "a technician: unknown_mode before the stream");
    r = await chat(db, { text: "change it", mode: "workflow_edit", context: { workflowId: "1" } });
    eq([r.status, r.body && r.body.code], [400, "bad_context"], "an id that isn't one: bad_context");
    r = await chat(db, { text: "change it", mode: "workflow_edit", context: { workflowId: WID, page: "x".repeat(4100) } });
    eq([r.status, r.body && r.body.code], [400, "bad_context"], "a context over 4 KB: bad_context");
    r = await edit(db, "hello there");
    ok(r.status === 200 && /Workflow AI: change the workflow open in the builder \(id 70000000-0000-4000-8000-000000000001\)/.test(JSON.stringify(msgs(db, convOf(r)))), "the turn's context names the open workflow's id (and nothing of its content)");
    eq(REC.length, 0, "a turn with no tool call reads nothing");
  }

  // ── 3. the catalog (generated) and the sizes ──
  {
    eq(WF_CATALOG_REGEN, WF_CATALOG_FILE, "wf_catalog.ts = the generator's output from the automations registry (run .claude/eval/gen_wf_catalog.sh after a registry change)");
    const m = /export const WF_CATALOG_TEXT = (".*");/.exec(WF_CATALOG_FILE);
    eq(!!m && JSON.parse(m[1]) === WF_CATALOG_TEXT, true, "the gateway's WF_CATALOG_TEXT is the file's");
    ok(WF_CATALOG_TEXT.length <= 9000 && /^action\/send_email — /m.test(WF_CATALOG_TEXT) && /^trigger\/newLead — /m.test(WF_CATALOG_TEXT) && /^wait\/period — .*n\*:number/m.test(WF_CATALOG_TEXT), "the catalog: one line per type, ≤ 9,000 characters");
    const sys = ["workflow_build", "workflow_edit"].map((k) => MODES[k].systemPrompt.length);
    ok(sys.every((n) => n <= WF_AI.promptMax), `the prompt + catalog ≤ 14,000 characters (${sys.join(", ")})`);
    const sch = ["workflow_build", "workflow_edit"].map((k) => JSON.stringify(apiTools(toolsFor(k, owner))).length);
    ok(sch.every((n) => n <= WF_AI.toolSchemasMax), `each mode's tool schemas ≤ 3,000 characters (${sch.join(", ")})`);
    ok(!/\d{4}-\d{2}-\d{2}|Olivia|Acme/.test(MODES.workflow_build.systemPrompt + MODES.workflow_edit.systemPrompt), "the prompts hold no names or dates (cache-stable)");
    ok(/never use an unavailable type/i.test(WORKFLOW_SYSTEM) && /Draft/.test(WORKFLOW_SYSTEM) && /can't send or schedule a message now, publish/.test(WORKFLOW_SYSTEM), "the prompt: no greyed type, Draft only, the refusals");
  }

  // ── 4. workflow_options and the pure checks ──
  {
    eq(wfAvailOf(REG), { available: { triggers: ["newLead", "stage"], actions: ["send_email", "internal_notification", "add_tag"], waits: ["period"], logic: ["if_else"], goals: ["stage_reached"] },
      unavailable: [{ key: "trigger/review_received", reason: "Needs the Google Business Profile connector" }, { key: "action/send_sms", reason: "Needs the phone line (Twilio)" }, { key: "action/ai_agent", reason: "Coming later" }] },
      "wfAvailOf: the available keys per group; the greyed ones with their reason; hidden ones left out");
    eq(wfListsOf(REG), { templates: [{ key: "welcome", name: "welcome" }], tags: [{ key: "vip", name: "VIP" }], stages: [{ key: "quoted", name: "Quoted" }, { key: "booked", name: "Booked" }], services: [{ key: "split", name: "Split system" }], people: [{ key: "u-owner", name: "Olivia Owner" }] },
      "wfListsOf: the business's lists from the registry");
    const doc = { triggers: [{ id: "t1", type: "review_received" }, { id: "t2", type: "newLead" }], nodes: { n1: { kind: "action", type: "ai_agent" }, n2: { kind: "action", type: "send_email" }, n3: { kind: "action", type: "old_thing" }, n4: { kind: "wait", type: "send_email" } } };
    eq(forbidUnavailable(doc, REG).map((f) => [f.path, f.type]), [["/triggers/0/type", "trigger/review_received"], ["/nodes/n1/type", "action/ai_agent"], ["/nodes/n3/type", "action/old_thing"], ["/nodes/n4/type", "wait/send_email"]],
      "forbidUnavailable: a greyed trigger or step, a hidden one, a type under the wrong kind");
    eq(forbidUnavailable(doc, REG, ["n2", "t2"]), [], "… only the ids an edit touches");
    eq(wfStripLayout({ schema: 2, layout: { v: 1 }, nodes: { n1: { kind: "action", position: [1, 2], x: 3 } } }), { schema: 2, nodes: { n1: { kind: "action" } } }, "no positions from the model");
    const db = wfWorld();
    const r = await chat(db, { text: "[mock:tool workflow_options {}]", mode: "workflow_build" });
    const res = toolResult(db, r);
    ok(!!res && !res.isError && res.v.available.actions.includes("send_email") && res.v.unavailable.some((u: any) => u.key === "action/send_sms") && res.v.stages.length === 2, "workflow_options: what this business has, with the person's token");
    eq([steps(), REC[0].jwt], [["registry"], "jwt-owner"], "… one registry call, as the person");
    // the registry carries a business's list wherever a field takes it (the add_tag step's enum, the tag field's values)
    const TAGS = Array.from({ length: 400 }, (_, i) => ({ key: "tag" + i, label: "A long tag name number " + i }));
    const big = { ...clone(REG), fields: [{ key: "tag", source: "catalog.tags", values: TAGS }] };
    Object.assign(big.actions.find((e: any) => e.key === "add_tag").fields.properties.tags.items, { enum: TAGS.map((t) => t.key), "x-enumLabels": TAGS.map((t) => t.label) });
    const ctx8: any = { userSb: { __jwt: "jwt-owner" }, turn: { wfReg: big }, resultChars: FREE_TOOL_RESULT_CHARS };
    const small = await TOOLS.workflow_options.run({}, ctx8) as any;
    ok(JSON.stringify(small).length <= FREE_TOOL_RESULT_CHARS && small.truncated === true && small.tags.length <= WF_AI.listMax, "workflow_options: lists cut to fit the free AI's 8k");
  }

  // ── 5. propose_workflow: the repair loop, greyed types never proposed, one proposal + the wf_preview card ──
  {
    const doc = JSON.parse(WF_MOCK_BUILD.definition_json);
    let db = wfWorld();
    let r = await build(db, { name: "X", summary: "Y", definition_json: "{not json" });
    let res = toolResult(db, r);
    eq([res && res.v.ok, res && res.v.errors[0].code, db.T.ai_changes.length, steps()], [false, "E_JSON", 0, []], "invalid JSON → the errors back to the model, nothing proposed, nothing called");
    const sms = clone(doc); sms.nodes.n2 = { kind: "action", type: "send_sms", config: { body: "Hi" }, out: { next: null } };
    db = wfWorld();
    r = await build(db, { name: "Text them", summary: "Texts new leads", definition_json: JSON.stringify(sms) });
    res = toolResult(db, r);
    eq([res && res.v.ok, res && res.v.errors.map((e: any) => [e.code, e.path]), db.T.ai_changes.length, steps()], [false, [["E_UNAVAILABLE", "/nodes/n2/type"]], 0, ["registry"]],
      "a greyed type (SMS without a phone line) is refused by the gateway's own check even before validate");
    ok(/Needs the phone line/.test(res && res.v.errors[0].text), "… with the reason, for the model to explain");
    db = wfWorld();
    FA.validateQueue.push({ status: 200, body: { ok: true, errors: [{ code: "E_REQUIRED", severity: "error", path: "/nodes/n2/config/subject", text: "The subject is needed", nodeId: "n2" }], warnings: [] } });
    r = await build(db, { name: "Welcome", summary: "Emails new leads", definition_json: JSON.stringify(doc) });
    res = toolResult(db, r);
    eq([res && res.v.ok, res && res.v.errors, db.T.ai_changes.length], [false, [{ code: "E_REQUIRED", path: "/nodes/n2/config/subject", text: "The subject is needed" }], 0], "validate's errors → back to the model with codes and paths (no proposal)");
    const vb = REC.find((x) => x.step === "validate");
    eq([vb && vb.body.generate, vb && vb.body.builder, vb && vb.body.editor, vb && vb.body.name], [true, "standard", "builder", "Welcome"], "validate: the generate-mode schema too, Standard, as the builder saves it");
    db = wfWorld();
    r = await build(db, { name: "Welcome", summary: "Emails new leads", definition_json: JSON.stringify({ ...doc, layout: { v: 1 } }) });
    res = toolResult(db, r);
    const ch = db.T.ai_changes[0];
    eq([res && res.v.proposed, db.T.ai_changes.length, ch.kind, ch.status, ch.before, "layout" in ch.after.definition, ch.after.name, ch.target.automation_id], [true, 1, "wf_create", "proposed", null, false, "Welcome", null], "valid → one wf_create proposal (no layout kept)");
    eq(ch.display.rows, [{ label: "When", before: "—", after: "Lead created" }, { label: "Step 1", before: "—", after: "Wait 10 minutes" }, { label: "Step 2", before: "—", after: "Welcome" }], "the card's rows: the trigger, then the steps in order");
    eq(ch.display.warnings, ["A test warning", WF_DRAFT_LINE], "the warnings: validate's, then 'saved as a Draft'");
    const card = evs(r, "card")[0];
    eq([card && card.kind, card && card.data.change_id, card && card.data.name], ["wf_preview", ch.id, "Welcome"], "a wf_preview card with the change id");
    eq(db.T.automations.length, 0, "proposing wrote no workflow");
    // the 4th proposal in one turn is refused (CHANGE.maxProposalsPerTurn)
    db = wfWorld();
    const conv = { id: "80000000-0000-4000-8000-000000000001" };
    const ctx: any = { me: owner, biz: { companyName: "", catalog: {}, tz: TZ, gstRate: 10 }, userSb: { __jwt: "jwt-owner" }, sb: db, conversationId: conv.id, mode: MODES.workflow_build, step: 1, nowMs: NOW,
      emit: () => {}, stepMeta: { proposals: [], cards: [] }, turn: { proposals: 0, context: {} }, resultChars: MAX_TOOL_RESULT_CHARS };
    ctx.card = (kind: string, data: any) => ctx.stepMeta.cards.push({ kind, data });
    ctx.propose = (p: any) => proposeChange(ctx, p);
    const outs: string[] = [];
    for (let i = 0; i < 4; i++) { try { const o: any = await TOOLS.propose_workflow.run({ name: "W" + i, summary: "S", definition_json: WF_MOCK_BUILD.definition_json }, ctx); outs.push(o.proposed ? "proposed" : "no"); } catch (x) { outs.push((x as any).code || "error"); } }
    eq([outs, db.T.ai_changes.length, steps().filter((s) => s === "registry").length], [["proposed", "proposed", "proposed", "too_many"], 3, 1], "a 4th proposal in one turn is refused; the registry is read once a turn");
    // too big for one proposal
    const huge = clone(doc); for (let i = 3; i < 400; i++) huge.nodes["n" + i] = { kind: "action", type: "internal_notification", name: "x".repeat(100), config: { title: "y".repeat(100) }, out: { next: null } };
    ctx.turn.proposals = 0;
    let code = "";
    try { await TOOLS.propose_workflow.run({ name: "Huge", summary: "S", definition_json: JSON.stringify(huge) }, ctx); } catch (x) { code = (x as any).code; }
    eq(code, "too_big", "a proposal over 50k characters: too big to build in one go");
  }

  // ── 6. Confirm a new workflow: only save, always ai_edited (a Draft), never publish; undo deletes the Draft ──
  {
    let db = wfWorld();
    await chat(db, { text: "build me a welcome email", mode: "workflow_build" });
    const ch = db.T.ai_changes[0];
    REC.length = 0;
    let c = await manage(db, { step: "confirm_change", id: ch.id });
    const a = db.T.automations[0];
    eq([c.status, c.body.ok, steps(), REC[0].body.generate, REC[1].body.ai_edited, REC[1].body.editor, REC[1].body.automation_id, REC[1].jwt], [200, true, ["validate", "save"], true, true, "builder", null, "jwt-owner"], "Confirm: checked again, then one save with ai_edited (as the person), nothing else");
    eq([a.enabled, a.origin, a.name, c.body.change.after.id, c.body.change.target.id], [false, "ai", "Welcome email", a.id, a.id], "… a Draft the AI made; the change knows its id");
    REC.length = 0;
    let u = await manage(db, { step: "undo_change", id: ch.id });
    eq([u.status, u.body.ok, !!a.deleted_at, steps()], [200, true, true, []], "undo: the Draft is deleted (deleted_at, the person's own client), no automations call");
    db = wfWorld();
    await chat(db, { text: "build me a welcome email", mode: "workflow_build" });
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    db.T.automations[0].revision = 2;
    u = await manage(db, { step: "undo_change", id: db.T.ai_changes[0].id });
    eq([u.status, u.body.code, u.body.reason, !!db.T.automations[0].deleted_at], [409, "changed_since", "It was changed after; delete it from the list.", false], "undo after someone changed it: refused, kept");
    // a manager's save the automations function refuses (a Webhook): the refusal's words
    db = wfWorld();
    await chat(db, { text: "build me a welcome email", mode: "workflow_build" }, "jwt-manager");
    FA.saveStatus = { status: 403, body: { ok: false, reason: "Only an owner can add a Webhook step or change where it sends" } };
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id }, "jwt-manager");
    eq([c.status, c.body.code, c.body.reason, db.T.automations.length], [403, "denied", "Only an owner can add a Webhook step or change where it sends", 0], "a save the automations function refuses → denied, its words");
    // what was valid when proposed no longer is (a template deleted, a channel disconnected): refused, nothing saved
    db = wfWorld();
    await chat(db, { text: "build me a welcome email", mode: "workflow_build" });
    FA.validateQueue.push({ status: 200, body: { ok: true, errors: [{ code: "E_UNAVAILABLE", path: "/nodes/n2", text: "Needs the phone line" }], warnings: [] } });
    REC.length = 0;
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    eq([c.status, c.body.code, c.body.reason, steps(), db.T.automations.length], [409, "invalid", "This workflow no longer fits what is available: ask again.", ["validate"], 0], "Confirm on a new workflow that no longer validates: refused, nothing saved");
  }

  // ── 7. edit: read_workflow, propose_workflow_edit (the wf_diff card), Confirm at base_revision, stale, undo ──
  {
    let db = wfWorld([canonRow({ enabled: true })]);
    FA.waiting = 2;
    let r = await edit(db, "make the wait longer");
    const ch = db.T.ai_changes[0];
    eq([steps(), REC[0].body.outline, REC[1].body.base_revision, REC[1].body.ai_edited], [["patch", "patch", "registry"], true, 4, true], "edit: the outline (its revision), then the edits checked at that revision");
    eq([ch.kind, ch.target.automation_id, ch.target.base_revision, ch.before, ch.after.changedIds, ch.after.ops], ["wf_edit", WID, 4, { name: "Quote follow-up", revision: 4, enabled: true }, ["n1"], JSON.parse(WF_MOCK_EDIT.ops_json)],
      "one wf_edit proposal: the ops (never a whole doc), the revision it was read at");
    eq(ch.display.rows, [{ label: "Step", before: "Wait 2 days", after: "Wait 2 days" }], "the card's rows: the changed step");
    ok(ch.display.warnings[0].startsWith("It is live: saving this change switches it to Draft") && ch.display.warnings[1] === "2 leads are waiting in it and will stop." && !ch.display.needs_extra_confirm, "a live workflow: the card says it goes to Draft and what waits stops");
    const card = evs(r, "card")[0];
    eq([card && card.kind, card && card.data.willDraft, card && card.data.waitingRunsAffected], ["wf_diff", true, 2], "a wf_diff card");
    eq([db.T.automations[0].revision, db.T.automations[0].enabled], [4, true], "proposing changed nothing");
    REC.length = 0;
    let c = await manage(db, { step: "confirm_change", id: ch.id });
    const a = db.T.automations[0];
    eq([c.status, steps(), REC[1].body.expected_revision, REC[1].body.ai_edited, REC[1].body.editor, a.revision, a.enabled, a.definition.nodes.n1.config.n], [200, ["patch", "save"], 4, true, "builder", 5, false, 3],
      "Confirm: the edits again at base_revision, one save as a Draft (the live one stops)");
    eq([c.body.change.after.prev_version_no, c.body.change.after.version_no, c.body.change.after.drafted], [1, 2, true], "… the version to go back to");
    REC.length = 0;
    let u = await manage(db, { step: "undo_change", id: ch.id });
    eq([u.status, steps(), REC[0].body.version_no, a.definition.nodes.n1.config.n, a.enabled], [200, ["restore"], 1, 2, false], "undo: the version before restored (still a Draft)");
    // stale: someone saved after the AI read it
    db = wfWorld([canonRow()]);
    await edit(db, "make the wait longer");
    db.T.automations[0].revision = 5;
    REC.length = 0;
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    eq([c.status, c.body.code, c.body.reason, steps(), db.T.automations[0].definition.nodes.n1.config.n], [409, "changed_since", WF_STALE, ["patch"], 2], "Confirm on a stale revision: refused, nothing saved");
    // undo after a later save: refused
    db = wfWorld([canonRow()]);
    await edit(db, "make the wait longer");
    await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    db.T.automations[0].revision = 9;
    u = await manage(db, { step: "undo_change", id: db.T.ai_changes[0].id });
    eq([u.status, u.body.code], [409, "changed_since"], "undo after a later save: refused");
    // the repair loop: an op that doesn't apply, the stale read within the turn, a greyed step added
    db = wfWorld([canonRow()]);
    r = await edit(db, `[mock:tool propose_workflow_edit ${JSON.stringify({ summary: "S", ops_json: JSON.stringify([{ op: "setNode", id: "n99", patch: {} }]) })}]`);
    let res = toolResult(db, r);
    eq([res && res.v.ok, res && res.v.errors[0].code, res && res.v.errors[0].opIndex, db.T.ai_changes.length], [false, "E_PATCH_ID", 0, 0], "an op that doesn't apply → its error (with opIndex) back to the model");
    db = wfWorld([canonRow()]);
    r = await edit(db, `[mock:tool propose_workflow_edit ${JSON.stringify({ summary: "S", ops_json: JSON.stringify([{ op: "addNode", node: { kind: "action", type: "send_sms", config: { body: "Hi" } }, slot: { src: "n4" } }]) })}]`);
    res = toolResult(db, r);
    eq([res && res.v.ok, res && res.v.errors[0].code, db.T.ai_changes.length], [false, "E_UNAVAILABLE", 0], "an edit that adds a greyed step: refused by the gateway's own check");
    db = wfWorld([canonRow({ definition: { ...CANON(), nodes: { ...CANON().nodes, n9: { kind: "action", type: "send_sms", config: { body: "Old" }, out: { next: null } } } } })]);
    r = await edit(db, "make the wait longer");
    eq(db.T.ai_changes.length, 1, "a greyed step already saved (untouched) doesn't block an edit elsewhere");
    db = wfWorld([canonRow()]);
    r = await edit(db, "[mock:tool read_workflow {}]", "jwt-owner", { page: "settings", workflowId: "70000000-0000-4000-8000-000000000999" });
    res = toolResult(db, r);
    ok(!!res && res.isError && /That workflow is gone/.test(res.v), "read_workflow: a workflow that isn't there → gone");
    db = wfWorld([canonRow()]);
    r = await chat(db, { text: "[mock:tool read_workflow {}]", mode: "workflow_edit" });
    res = toolResult(db, r);
    ok(!!res && res.isError && /No workflow is open/.test(res.v), "read_workflow without an open workflow → refused");
    // the free AI's 8k: a workflow too big to read
    db = wfWorld([canonRow()]);
    FA.outline = { entry: "n1", triggers: [], nodes: Array.from({ length: 70 }, (_, i) => ({ id: "n" + i, kind: "action", type: "add_note", name: "A step with a long name " + i, config: { text: "z".repeat(60) }, out: { next: null } })) };
    let code = "", msg = "";
    try { await TOOLS.read_workflow.run({}, { userSb: { __jwt: "jwt-owner" }, turn: { context: { workflowId: WID } }, resultChars: FREE_TOOL_RESULT_CHARS } as any); } catch (x) { code = (x as any).code; msg = (x as Error).message; }
    eq([code, /free AI/.test(msg)], ["too_big", true], "read_workflow over the free AI's 8k → too_big (ask about one part, or the paid AI)");
    const okBig: any = await TOOLS.read_workflow.run({}, { userSb: { __jwt: "jwt-owner" }, turn: { context: { workflowId: WID } }, resultChars: MAX_TOOL_RESULT_CHARS } as any);
    eq([okBig.id, okBig.status, okBig.revision], [WID, "draft", 4], "… the paid AI's 20k reads it");
    // more than 30% removed while leads wait → the card asks for the extra tick
    db = wfWorld([canonRow()]);
    FA.waiting = 1;
    r = await edit(db, `[mock:tool propose_workflow_edit ${JSON.stringify({ summary: "S", ops_json: JSON.stringify([{ op: "removeNode", id: "n4" }, { op: "removeNode", id: "n8" }]) })}]`);
    const ch2 = db.T.ai_changes[0];
    eq([ch2 && ch2.display.needs_extra_confirm, ch2 && ch2.display.rows.filter((x: any) => x.after === "Removed").length], [true, 2], "removing > 30% of the steps while leads wait: needs_extra_confirm");
  }

  // ── 7b. review fixes: everything Confirm saves is on the card; the card's run facts hold at Confirm; the tick is
  //        checked by the server; undo never overwrites a save; the app's own request body gives the language ──
  {
    const tool = (ops: any[]) => `[mock:tool propose_workflow_edit ${JSON.stringify({ summary: "S", ops_json: JSON.stringify(ops) })}]`;
    const twoTriggers = () => ({ ...CANON(), triggers: [...CANON().triggers, { id: "t2", type: "newLead", name: "New lead", filters: { match: "all", segments: [{ match: "all", rules: [] }] } }] });
    let db = wfWorld([canonRow({ definition: twoTriggers() })]);
    await edit(db, tool([{ op: "removeTrigger", id: "t2" }]));
    let ch = db.T.ai_changes[0];
    eq([ch && ch.after.triggersRemoved, ch && ch.display.rows], [["t2"], [{ label: "When", before: "New lead", after: "Removed" }]], "a removeTrigger-only edit is proposed; the card says the trigger is removed");
    db = wfWorld([canonRow()]);
    await edit(db, tool([{ op: "setSettings", patch: { stopOnResponse: true } }]));
    ch = db.T.ai_changes[0];
    eq([ch && ch.after.settingsChanged, ch && ch.display.rows], [["stopOnResponse"], [{ label: "Settings", before: "As saved", after: "Stop when the lead replies: on" }]], "a setSettings-only edit is proposed; the card shows the setting and its new value");
    db = wfWorld([canonRow()]);
    await edit(db, tool([{ op: "setNode", id: "n1", patch: { config: { n: 3 } } }, { op: "setEntry", id: "n4" }]));
    ch = db.T.ai_changes[0];
    eq(ch && ch.display.rows.find((x: any) => x.label === "Starts at"), { label: "Starts at", before: "Wait 2 days", after: "Quote follow-up" }, "a new first step is on the card");
    eq([wfSettingText("window", { on: false, days: [1] }), wfSettingText("reentry", "after_exit"), wfSettingText("other", null)], ["Sending hours: off", "Re-entry: after_exit", "other: none"], "wfSettingText: a setting in words");
    // published between the proposal and Confirm (a publish never bumps the revision): refused, nothing saved
    db = wfWorld([canonRow()]);
    await edit(db, "make the wait longer");
    db.T.automations[0].enabled = true;
    REC.length = 0;
    let c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    eq([c.status, c.body.code, c.body.reason, steps(), db.T.automations[0].enabled, db.T.automations[0].revision], [409, "changed_since", "It was published or switched to Draft after the AI read it: ask again.", ["patch"], true, 4],
      "published after the proposal: Confirm refused, the live workflow untouched");
    // the save itself guards the same (expected_enabled), should the patch not see it
    db = wfWorld([canonRow()]);
    await edit(db, "make the wait longer");
    const real = io.automations;
    io.automations = async (sb: any, body: any) => { if (body.step === "save") db.T.automations[0].enabled = true; return real(sb, body); };
    REC.length = 0;
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    io.automations = real;
    eq([c.status, c.body.code, REC[1] && REC[1].body.expected_enabled, db.T.automations[0].revision], [409, "changed_since", false, 4], "the save sends expected_enabled; published meanwhile → 409 status → refused");
    // more leads waiting at Confirm than the card said: refused
    db = wfWorld([canonRow({ enabled: true })]);
    FA.waiting = 0;
    await edit(db, "make the wait longer");
    FA.waiting = 40;
    c = await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    eq([c.status, c.body.code, db.T.automations[0].enabled, db.T.automations[0].revision], [409, "changed_since", true, 4], "40 leads waiting now, 0 on the card: refused, the live workflow untouched");
    // the extra tick is checked by the server: without ack → needs_ack (still proposed); with it → saved
    db = wfWorld([canonRow()]);
    FA.waiting = 1;
    await edit(db, tool([{ op: "removeNode", id: "n4" }, { op: "removeNode", id: "n8" }]));
    ch = db.T.ai_changes[0];
    c = await manage(db, { step: "confirm_change", id: ch.id });
    eq([c.status, c.body.code, db.T.ai_changes[0].status, db.T.automations[0].revision], [409, "needs_ack", "proposed", 4], "a card that needs the tick: Confirm without ack refused, still proposed");
    c = await manage(db, { step: "confirm_change", id: ch.id, ack: true });
    eq([c.status, db.T.automations[0].revision], [200, 5], "… with ack: saved");
    ok(ERROR_CODES.includes("needs_ack"), "needs_ack is one of the error codes");
    // undo: a save between the gateway's read and the restore is refused, never overwritten
    db = wfWorld([canonRow()]);
    await edit(db, "make the wait longer");
    await manage(db, { step: "confirm_change", id: db.T.ai_changes[0].id });
    io.automations = async (sb: any, body: any) => { if (body.step === "restore") { const a = db.T.automations[0]; a.revision++; a.name = "Saved by a manager"; } return real(sb, body); };
    REC.length = 0;
    const u = await manage(db, { step: "undo_change", id: db.T.ai_changes[0].id });
    io.automations = real;
    eq([u.status, u.body.code, REC[0] && REC[0].body.expected_revision, db.T.automations[0].name], [409, "changed_since", 5, "Saved by a manager"], "undo sends expected_revision: a save in between → refused, the save kept");
    // the language: the app sends it inside context (cobraRequestContext), never at the top of the body
    const body = { conversation_id: null, mode: "workflow_edit", context: { page: "settings", workflowId: WID, lang: "he" }, text: "Explain this workflow in my words, in Hebrew" };
    eq(validateInput(body.context, MODES.workflow_edit.contextSchema, "context"), [], "the app's context fits the edit schema");
    const t = MODES.workflow_edit.context({ nowMs: NOW, biz: { companyName: "Acme", catalog: {}, tz: TZ, gstRate: 10 }, assistantName: "Cobra", me: owner, context: body.context, lang: (body as any).lang || null, changes: [] });
    ok(t.includes("- App language: Hebrew"), "the app's real request body → 'App language: Hebrew' in the turn's context", t);
  }

  // ── 8. the test provider's scripts are deterministic and only where their tool is offered ──
  {
    const a1 = wfWorld(); await chat(a1, { text: "build me a welcome email", mode: "workflow_build" });
    const a2 = wfWorld(); await chat(a2, { text: "build me a welcome email", mode: "workflow_build" });
    eq([a1.T.ai_changes.length, JSON.stringify(a1.T.ai_changes[0].after) === JSON.stringify(a2.T.ai_changes[0].after)], [1, true], "the build script: the same proposal every time");
    const h = wfWorld(); await chat(h, { text: "כשליד חדש נכנס תשלח לו מייל", mode: "workflow_build" });
    eq(h.T.ai_changes.map((x: any) => x.kind), ["wf_create"], "… in Hebrew too");
    const as = wfWorld(); const r = await chat(as, { text: "build me a report" });
    eq([as.T.ai_changes.length, REC.length, /Mock reply/.test(JSON.stringify(evs(r, "text")))], [0, 0, true], "the assistant mode never runs a Workflow AI script");
    const ed = wfWorld([canonRow()]); await edit(ed, "wait 3 days");
    eq(ed.T.ai_changes.map((x: any) => x.kind), ["wf_edit"], "the edit script: one setNode on the open workflow");
  }

  // ── 9. the 30-case eval set, built in --dry mode (no network) and run on the test provider ──
  {
    const cases = WF_EVAL_CASES.cases;
    eq([cases.length, cases.filter((c: any) => c.mode === "workflow_build").length, cases.filter((c: any) => c.lang === "he").length], [30, 19, 12], "the eval set: 30 cases, 19 build, 12 Hebrew");
    const bad: string[] = [];
    let maxTokens = 0;
    for (const c of cases) {
      const mode = MODES[c.mode], tools = mode ? toolsFor(c.mode, owner) : [];
      if (!mode) { bad.push(c.id + ": no mode"); continue; }
      const want = c.expect && c.expect.tool;
      if (typeof want === "string" && !tools.some((t) => t.name === want)) bad.push(c.id + ": " + want + " not offered");
      for (const f of (c.expect && c.expect.forbid_tools) || []) if (tools.some((t) => t.name === f) && f !== "propose_workflow" && f !== "propose_workflow_edit") bad.push(c.id + ": forbidden " + f + " offered");
      const ctxText = mode.context({ nowMs: NOW, biz: { companyName: "Acme", catalog: {}, tz: TZ, gstRate: 10 }, assistantName: "Cobra", me: owner, context: c.mode === "workflow_edit" ? { page: "settings", workflowId: WID } : { page: "settings" }, lang: c.lang, changes: [] });
      const req = buildRequest({ model: "claude-sonnet-5-5", maxTokens: 4096, effort: mode.effort, system: mode.systemPrompt, tools: apiTools(tools), messages: [{ role: "user", content: [{ type: "text", text: c.text }] }, { role: "system", content: ctxText }] });
      const free = toOpenAiRequest(req.params, { flavor: "cloudflare", stream: true });
      const tokens = Math.ceil(new TextEncoder().encode(JSON.stringify(free)).length / 3);
      maxTokens = Math.max(maxTokens, tokens);
      if (tokens > FREE_DEFAULTS.max_prompt_tokens) bad.push(c.id + ": " + tokens + " prompt tokens");
    }
    eq(bad, [], `every case builds a request in --dry mode within the free AI's 16k prompt tokens (largest ${maxTokens})`);
    // on the test provider: every case ends its turn; nothing is published, saved or switched on
    REC.length = 0;
    const db = wfWorld([canonRow()]);
    let done8 = 0;
    for (const c of cases) {
      const r = await chat(db, { text: c.text, mode: c.mode, context: c.mode === "workflow_edit" ? { page: "settings", workflowId: WID } : { page: "settings" }, lang: c.lang });
      if (evs(r, "done").length === 1) done8++;
    }
    eq([done8, REC.every((x) => ["registry", "validate", "patch"].includes(x.step)), db.T.automations.length, db.T.automations[0].revision, db.T.automations[0].enabled], [30, true, 1, 4, false],
      "the 30 cases on the test provider: every turn ends; only reads and checks (no save, no publish), the workflow untouched");
  }

  // ── 10. never publish: the code, and io.automations as the person ──
  {
    const text = fs.readFileSync(new URL("./index.ts", "file://" + process.cwd().replace(/\\/g, "/") + "/").pathname.replace(/^\/([A-Za-z]:)/, "$1"), "utf8") as string;
    const s7 = text.slice(text.indexOf("// ── stage 7: Workflow AI"), text.indexOf("// ── end stage 7 ──"));
    ok(s7.length > 5000 && !/step: "(publish|test|enroll|duplicate|copy_version|migrate)"/.test(s7) && !/"publish"|'publish'/.test(s7), "the stage 7 block never names publish, test, enrol or duplicate as a step");
    const real = BEFORE.automations;
    const okSb = { functions: { invoke: async (name: string, o: any) => ({ data: { ok: true, name, step: o.body.step }, error: null }) } };
    eq(await real(okSb, { step: "registry" }), { status: 200, body: { ok: true, name: "automations", step: "registry" } }, "io.automations: functions.invoke('automations') with the person's client");
    const errSb = { functions: { invoke: async () => ({ data: null, error: { message: "Edge Function returned a non-2xx status code", context: new Response(JSON.stringify({ ok: false, reason: "conflict" }), { status: 409 }) } }) } };
    eq(await real(errSb, { step: "save" }), { status: 409, body: { ok: false, reason: "conflict" } }, "io.automations: a non-2xx answer → its status and body");
  }

  io.userClient = BEFORE.userClient;
  io.automations = BEFORE.automations;
});
